import { delegate, type SafeHtml } from 'kerfjs';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarText } from '@kerfjs/ui/toolbar-text';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { PageHeader } from '@kerfjs/ui/page-header';
import { ResizableRegion } from '@kerfjs/ui/resizable-region';
import { wireResizableRegions } from '@kerfjs/ui/wire-resizable-regions';
import { ValueTable } from '@kerfjs/ui/value-table';
import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/sidebar.css';
import './shell.css';

type Route = 'inbox' | 'projects' | 'archive';
type PhonePane = 'navigation' | 'workspace' | 'inspector';
export interface ShellApplication {
  renderInto(root: HTMLElement, view: SafeHtml): void;
  workspace(route: Route): SafeHtml;
  inspector(): SafeHtml;
  loadInspectorWidth(): number | undefined;
  saveInspectorWidth(width: number): void;
  navigate(route: Route): void;
}
export function mountShell(root: HTMLElement, app: ShellApplication) {
  let route: Route = 'inbox';
  const stored = app.loadInspectorWidth();
  let width = Number.isFinite(stored) ? Math.max(200, Math.min(400, stored!)) : 280;
  let inspectorOpen = true;
  let phonePane: PhonePane = 'workspace';
  const media = window.matchMedia('(max-width: 60rem)');
  let narrow = media.matches;
  const navigation = () => <nav aria-label="Workspace navigation" class="shell-nav kui-sidebar kui-scroll-owner">
    <section class="kui-sidebar-section"><MenuHeader label="Workspace" />
      <MenuItem action="shell.navigate" itemId="inbox" label="Inbox" selected={route === 'inbox'} />
      <MenuItem action="shell.navigate" itemId="projects" label="Projects" selected={route === 'projects'} />
    </section>
    <section class="kui-sidebar-section"><MenuHeader label="Library" />
      <MenuItem action="shell.navigate" itemId="archive" label="Archive" selected={route === 'archive'} />
    </section>
  </nav>;
  const details = () => <aside class="shell-pane" aria-label="Inspector">
    <h2 class="shell-pane-title">Inspector</h2>
    <div class="kui-scroll-owner kui-pane-body kui-section-stack">
      <ValueTable label="Workspace context"><div><dt>Section</dt><dd>{route}</dd></div></ValueTable>
      {app.inspector()}
    </div>
  </aside>;
  const workspace = () => <main class="shell-pane" id="shell-workspace" tabindex="-1">
    <PageHeader title={route === 'inbox' ? 'Inbox' : route === 'projects' ? 'Projects' : 'Archive'} />
    <div class="kui-scroll-owner kui-pane-body">{app.workspace(route)}</div>
  </main>;
  function render() {
    app.renderInto(root, <div class="shell kui-layout">
      <Toolbar label="Application controls" leading={<ToolbarText text="Workspace" />}
        trailing={<ToolbarControlGroup appearance="borderless" label="Visible panes">
          {narrow ? <>
            <button type="button" data-action="shell.pane" data-pane="navigation" aria-pressed={String(phonePane === 'navigation')}>Navigation</button>
            <button type="button" data-action="shell.pane" data-pane="workspace" aria-pressed={String(phonePane === 'workspace')}>Workspace</button>
            <button type="button" data-action="shell.pane" data-pane="inspector" aria-pressed={String(phonePane === 'inspector')}>Inspector</button>
          </> : <button type="button" data-action="shell.inspector" aria-expanded={String(inspectorOpen)} aria-controls="shell-inspector">Inspector</button>}
        </ToolbarControlGroup>} />
      <div class="shell-body">
        {narrow ? (phonePane === 'navigation' ? navigation() : phonePane === 'inspector' ? details() : workspace()) : <>
          {navigation()}{workspace()}
          {inspectorOpen && <ResizableRegion id="shell-inspector" label="Inspector width" size={width} min={200} max={400} edge="start">{details()}</ResizableRegion>}
        </>}
      </div>
    </div>);
  }
  render();
  const actions = delegate(root, 'click', '[data-action]', (_event, element) => {
    if (!(element instanceof HTMLElement)) return;
    switch (element.dataset.action) {
      case 'shell.navigate': {
        const next = element.dataset.itemId;
        if (next !== 'inbox' && next !== 'projects' && next !== 'archive') return;
        route = next; app.navigate(route);
        if (narrow) phonePane = 'workspace';
        render();
        root.querySelector<HTMLElement>('#shell-workspace')?.focus();
        break;
      }
      case 'shell.pane': {
        const next = element.dataset.pane;
        if (next !== 'navigation' && next !== 'workspace' && next !== 'inspector') return;
        phonePane = next; render(); break;
      }
      case 'shell.inspector': inspectorOpen = !inspectorOpen; render(); break;
    }
  });
  // Package wiring owns separator arrows, Shift+arrows, Home/End and pointer drag.
  // The width remains application state, including while the inspector is closed.
  const resize = wireResizableRegions(root, {
    onResize: ({ id, size, phase }) => {
      if (id !== 'shell-inspector') return;
      width = Math.max(200, Math.min(400, size));
      render();
      if (phase === 'commit') app.saveInspectorWidth(width);
    },
  });
  const responsive = () => {
    const hadPaneFocus = root.contains(document.activeElement) && !root.querySelector('.kui-toolbar')?.contains(document.activeElement);
    narrow = media.matches;
    render();
    if (hadPaneFocus) root.querySelector<HTMLElement>('[data-action="shell.pane"], [data-action="shell.inspector"]')?.focus();
  };
  media.addEventListener('change', responsive);
  return () => { actions(); resize(); media.removeEventListener('change', responsive); };
}

