.shell { block-size: 100dvh; display: grid; grid-template-rows: auto minmax(0, 1fr); min-inline-size: 0; overflow: hidden; color: var(--kui-color-text); background: var(--kui-color-surface); }
.shell-body { display: flex; min-width: 0; min-height: 0; }
.shell-nav { flex: 0 0 14rem; min-height: 0; padding-block: var(--kui-layout-pane-inset); }
.shell-pane { flex: 1; display: grid; grid-template-rows: auto minmax(0, 1fr); min-width: 0; min-height: 0; height: 100%; }
.shell-pane-title { font-size: var(--kui-font-l); margin: 0; padding: var(--kui-space-m); border-block-end: 1px solid var(--kui-color-border); }
.shell .kui-scroll-owner { min-height: 0; min-width: 0; overscroll-behavior: contain; overflow-wrap: anywhere; }
.shell :focus-visible { outline: var(--kui-focus-ring); outline-offset: 2px; }
@media (max-width: 60rem) {
  .shell-body > * { flex: 1; width: 100%; }
  .shell .kui-toolbar { height: auto; grid-template-columns: minmax(0, 1fr); gap: var(--kui-layout-control-gap); }
  .shell .kui-toolbar__trailing { justify-content: flex-start; }
}
